pub fn main() void {
    // Euclidean algorithm for GCD of 1071 and 462
    var a: i64 = 1071;
    var b: i64 = 462;

    while (b != 0) {
        // Swap if a < b
        if (a < b) {
            a = b;
            b = a % b;
        } else {
            a = a % b;
            b = b;
        }
    }

    // Print the result
    std.debug.print("GCD: {d}\n", .{a});
}
